local _, WFJ = ...
WFJ.Data.add("quest", {
  [94003] = { "Lo Skybreaker Bulwark", "Recupera lo Skybreaker Bulwark da Zaal Stormshield allo Shrine of Akir.", "Sono tutto ciò che resta della stirpe degli Skybreaker qui sull'isola di Zephras. Gli altri sono stati assassinati dagli Al'Aketh.\n\nL'unica cosa che supera il mio dolore è la mia vergogna. Lo scudo ancestrale della mia famiglia, lo Skybreaker Bulwark, è ora nelle mani di un cultista di nome Zaal Stormshield. Secondo le leggende di famiglia, nessun male può colpire chi impugna questo scudo ed è degno di esso.\n\nZaal non ne è degno, di questo sono certo. Trova quell'uomo allo Shrine of Akir e riprenditi il mio scudo. Fallo e ti insegnerò la Skybreaker Defense.", nil, nil, 0xeef30912, 0x2a671f64, 0x9c8826cf, nil, nil, "...mm" },
  [94004] = { "Contratto d'Artigianato: Elisir della Forza degli Ogre", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritto con un inchiostro sbiadito, il biglietto richiede $N1 Elisir della Forza degli Ogre e riporta indicazioni sul luogo di consegna e sul pagamento. In fondo, una scritta indica che il contratto è cedibile.>", nil, nil, 0x96235fbe, 0x89b8e7e5, 0xceb296e5, nil, nil, "...mm" },
  [94006] = { "Il grande spirito ursera", "Parla con Urs'endris vicino alle cascate a nord-est di Valanaar.", "Salute, {name}. Sei andat<o/a> abbastanza avanti nei tuoi studi druidici da farmi pensare che sia ora di conoscere uno dei grandi spiriti che dimorano qui a Zephras. Urs'endris è uno spirito saggio e nobile, che da generazioni insegna ai druidi ad assumere la forma di ursera. Purtroppo il suo dominio ha cominciato ad avvizzire e a precipitare nel cielo, come molte altre zone di Zephras.\n\nPer trovarlo, va' a nord-est, vicino alla cascata all'ombra dello Shrine of Akir. Lui saprà guidarti oltre.", nil, nil, 0xd845fe86, 0x00a57812, 0x6204789e, nil, nil, "...mm" },
  [94007] = { "Addomesticare la bestia", "Fai rapporto a Quel'ana Quickgale a Valanaar.", "Ora che hai preso una certa confidenza con le terre selvagge degli altopiani, credo sia giunto il momento che tu cerchi un compagno animale tutto tuo.\n\nVa' al porto di Valanaar, a sud-est, e parla con Quel'ana Quickgale. Ti istruirà nell'arte di ammansire le bestie.", nil, nil, 0xecd97a9a, 0x87db1216, 0xab76e227, nil, nil, "...mm" },
  [94013] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per ammansire un Vuldren Alpha nei Gustberry Lowlands. Esercita le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Quel'ana Quickgale a Valanaar.", "Sei <tornato/tornata> vittorios<o/a> dopo aver ammansito due bestie. Ora è il momento della tua ultima prova. I venti di Zephras sussurrano di sfide più grandi in arrivo.\n\nPrendi questo ⟦Taming Rod=Bastone per Addomesticare⟧ e recati nei Gustberry Lowlands. Lì ammansisci un Vuldren Alpha e dimostra la tua maestria.\n\nCompleta questa lezione e sarai <pronto/pronta> ad apprendere le vie più profonde del cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", "Eccellente, {name}! Impari davvero in fretta. Ora che conosci le basi, posso insegnarti a stringere un legame duraturo con un compagno animale.\n\nVa' con questa conoscenza e prospera. Sii <il/la> {class} di cui l'isola di Zephras ha bisogno.", 0xecd97a9a, 0xd6749188, 0x420fabee, 0xe5057f89, 0x5c64ed8c, "....." },
  [94050] = { "Addestrare la bestia", "Parla con Quel'dora Quickgale a Valanaar.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di mia sorella, Quel'dora. Ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nVa' con i venti, giovane {class}.", nil, "<Un/Una> {class} alle prime armi, vedo. Sì, posso darti le capacità che ti servono per addestrare e guidare il tuo famiglio. Non solo potrai insegnare al tuo famiglio nuove abilità, ma d'ora in poi potrai anche nutrirlo e riportarlo in vita, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con riverenza verso la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0xa8d2fa5d, 0x1f82d9d8, nil, 0xfbd746d0, "...m." },
  [94212] = { "Contratto d'Artigianato: ⟦Elixir of Wisdom=Elisir della Saggezza⟧", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritto con un inchiostro sbiadito, il biglietto richiede $N1 ⟦Elixir of Wisdom=Elisir della Saggezza⟧ e riporta indicazioni sul luogo di consegna e sul pagamento. In fondo, una scritta indica che il contratto è cedibile.>", nil, nil, 0xbe3bb0e2, 0x89b8e7e5, 0x4ac2ada9, nil, nil, "...mm" },
