  [94357] = { "Contratto d'Artigianato: ⟦Cenarion Herb Bag=Sacca per Erbe Cenariana⟧", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritta con un inchiostro sbiadito, la nota richiede $N1 ⟦Cenarion Herb Bag=Sacca per Erbe Cenariana⟧, con le indicazioni sul luogo di consegna e sul pagamento. In fondo compare una dicitura secondo cui il contratto è cedibile.>", nil, nil, 0x69c4d25e, 0x89b8e7e5, 0x3af81970, nil, nil, "...mm" },
  [94358] = { "Contratto d'Artigianato: ⟦Shadoweave Mask=Maschera di Stoffa dell'Ombra⟧", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritta con un inchiostro sbiadito, la nota richiede $N1 ⟦Shadoweave Mask=Maschera di Stoffa dell'Ombra⟧, con le indicazioni sul luogo di consegna e sul pagamento. In fondo compare una dicitura secondo cui il contratto è cedibile.>", nil, nil, 0x98796734, 0x89b8e7e5, 0xcc7dfbdd, nil, nil, "...mm" },
  [94359] = { "Contratto d'Artigianato: ⟦Ghostweave Vest=Veste di Tessuto Fantasma⟧", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritta con un inchiostro sbiadito, la nota richiede $N1 ⟦Ghostweave Vest=Veste di Tessuto Fantasma⟧, con le indicazioni sul luogo di consegna e sul pagamento. In fondo compare una dicitura secondo cui il contratto è cedibile.>", nil, nil, 0x8cf903cf, 0x89b8e7e5, 0x8ace6ad3, nil, nil, "...mm" },
  [94360] = { "Contratto d'Artigianato: ⟦Soul Pouch=Borsa dell'Anima⟧", "Procurati gli oggetti richiesti dal cliente e consegnali nel luogo segnato sulla mappa. Per completare la transazione devi avere con te questo contratto.", "<Scritta con un inchiostro sbiadito, la nota richiede $N1 ⟦Soul Pouch=Borsa dell'Anima⟧, con le indicazioni sul luogo di consegna e sul pagamento. In fondo compare una dicitura secondo cui il contratto è cedibile.>", nil, nil, 0xbdabef1c, 0x89b8e7e5, 0x0b60ca87, nil, nil, "...mm" },
  [94369] = { "Il destino di Zephras", "Parla con Talaanis Shadowsong a Valanaar.", "Ansirem mi ha raccontato molto dei signori elementali, e temo che ora abbiamo buone ragioni per temere Al'Akir, adesso che le protezioni che nascondevano Zephras sono cadute. Se il Signore del Vento decidesse di attaccarci, non avremmo alcuna possibilità di difenderci finché siamo qui, nel suo dominio.\n\nL'alto anziano Shadowsong deve sapere del pericolo che corriamo e, soprattutto, quali sono le nostre intenzioni per la nostra missione su Azeroth. Troveremo il modo di salvare la nostra casa. Lo giuro.", nil, "<Talaanis Shadowsong ascolta con attenzione mentre gli racconti ciò che è accaduto sopra lo Shrine of Akir e del piano di Elaadrin di lasciare Zephras Isle.>\n\nDevo rifletterci ancora, ma guardando il lato positivo, ci siamo liberati di Lorthuna e abbiamo privato il culto della sua guida. La nostra casa non è ancora stata invasa e, con i tempi dei semidei elementali, potrebbero passare anni... persino decenni, prima che Al'Akir si degni di rivolgere a noi la sua attenzione.\n\nC'è molto da temere, ora, ma anche molto da festeggiare.", 0x6d3ea2fe, 0x4440ff8a, 0xbee20486, nil, 0xb4e92149, "...m." },
  [94373] = { "Il richiamo della terra", "Porta 2 Frostmane Bear Pendant a Teo Hammerstorm a ⟦Anvilmar=Forgiamara⟧.", "Sì, è giunto il momento, giovane <sciamano/sciamana>. Sei cresciut<o/a> robust<o/a> e solid<o/a>, come la pietra sotto i nostri stivali. Intraprendere il sentiero dello sciamano dimostra che hai la saggezza della montagna, ancor prima di aver dato prova di te. Hai la tempra della pietra per percorrere il sentiero della terra.\n\nMa per guadagnarti il suo favore devi affrontarla come si deve. A sud di qui, i troll ⟦Frostmane=Mantogelido⟧ vivono in una grotta.\n\nPortami due delle collane che indossano, fatte con gli orsi Iceclaw. Poi parleremo ancora del tuo futuro.", "La pazienza, <ragazzo/ragazza>, è la virtù più bella della terra. Ha visto montagne sgretolarsi e fiumi scavare valli: lenta e testarda, come un vero {race}. Ora la terra ti chiama, perché all'orizzonte si prepara qualche guaio. Torna con un successo e sarai un passo più vicin<o/a> a essere complet<o/a>.\n\nAltri potranno invidiare la tua saggezza, ma quello è un fardello che tocca a loro portare.", "Ben fatto, <ragazzo/ragazza>. Hai dimostrato di essere <pronto/pronta>. La terra è il fondamento di tutte le cose. Forza, resistenza, pazienza. Ti farà da scudo, ma solo se le porterai il rispetto che merita. Anche la pietra può muoversi se viene offesa. Impara le sue vie e diventerai più saggi<o/a> della maggior parte della gente. Non dimenticare mai i segreti che condivide.\n\nOra ti preparerò un sapta: accettalo e percorrerai il vero sentiero.", 0xe316c17f, 0xc897beee, 0x70173b78, 0xd804d26a, 0xb1f39df1, "....." },
  [94374] = { "Il richiamo della terra", "Trova la Spirit Stone e bevi il ⟦Earth Sapta=Sapta di Terra⟧.", "Sì, il sapta è un intruglio forgiato con la magia, che lega il nostro spirito agli elementi. Solo pochi sciamani ne conoscono la ricetta, e non è roba per chi ha la volontà debole. Bevilo e vedrai ciò che gli altri non possono vedere. Ricorda bene: va bevuto solo in un luogo sacro.\n\nDirigiti a nord verso la Spirit Stone, nascosta in fondo a un sentiero segreto su per la montagna. Bevilo lì... e guarda cosa ha da mostrarti la terra.", nil, "Ah... {name}... la terra ti accoglie, anche in questa terra gelata. Unit<o/a> nel corpo e nello spirito, andrai avanti sapendo che le montagne sono la tua forza, le pianure la tua pazienza e il mondo la tua essenza.\n\nPer superare questo rito, presentati con umiltà davanti alla terra. Gli altri elementi non sono così quieti: si scontrano e ruggiscono. Impara la loro duplice natura, anche qui tra la neve e la pietra.", 0xe316c17f, 0x4c31146f, 0x28284db1, nil, 0xcd853d2f, "...m." },
  [94375] = { "Il richiamo della terra", "Porta il ⟦Rough Quartz=Quarzo Grezzo⟧ a Teo Hammerstorm a ⟦Anvilmar=Forgiamara⟧.", "Prendi da me questo quarzo grezzo e portalo a Teo Hammerstorm come prova del nostro incontro. Creerà un totem per te, e questo sassolino ne sarà il cuore. Per quanto possa sembrare piccolo, scoprirai che la grandezza non conta, e che anche le cose più piccole possono durare più di molte altre.\n\nSii paziente, {name}. Resta saldo nello spirito. E cerca la saggezza. Questo è ciò che la terra ti chiede. Alla fine diventerai una cosa sola con la terra: rispettala, come lei rispetterà te.", "Ahh, sei tornat<o/a>. Se hai la pietra, vuol dire che la montagna ti ha scelt<o/a> davvero. Ti darò il totem che ti ha promesso. Ma se sei venut<o/a> a mani vuote, fuori dai piedi! Il sentiero non è per chi dimentica la propria strada.", nil, 0xe316c17f, 0x1c898e3e, 0x1415c33d, 0xa9c8dad9, nil, "....m" },
  [94411] = { "Maghi impiccioni", "Uccidi 6 High Order Apprentice negli Shen'dar Highlands.", "Sta' in guardia: alcuni membri dell'High Order sono stati visti nei pressi delle pietre erette a nord del villaggio. Li abbiamo avvertiti più e più volte di non immischiarsi nei nostri luoghi sacri, ma si fanno sempre più audaci nello sfidarci. Dimostraci la tua determinazione: va' alle pietre erette e disperdili.\n\nMi ripugna approvare uno spargimento di sangue vero e proprio, ma fa' ciò che devi per scacciarli. Torna da me quando avrai finito.", nil, "Lo scontro diretto con i nostri fratelli e sorelle shen'dorei non fa che indebolirci come popolo, ma a volte bisogna agire con decisione per evitare una tragedia più grande.\n\nI maghi dell'High Order non tengono in alcun conto le conseguenze delle loro ingerenze magiche. Le forze che legano la nostra isola sono fragili e vulnerabili, e potrebbe bastare un solo gesto sconsiderato per distruggere la nostra casa.", 0xf63c825c, 0xff42e97b, 0x0bc960b1, nil, 0x717d680d, "...m." },
  [94413] = { "Un affronto magico", "Uccidi 6 Windshaper Novice Seer negli Shen'dar Highlands.", "Il recente affiorare delle linee di energia sulla superficie di Zephras è stato un evento profondo per il nostro ordine. Abbiamo un accesso più diretto e tangibile alle energie che permeano questo luogo, e la nostra comprensione di questa magia è cresciuta enormemente.\n\nI Windshaper, però, vedono questi affioramenti come cicatrici sulla terra che vanno «guarite». È un affronto al nostro ordine, qualcosa che proprio non possiamo tollerare.\n\nVa' alla linea di energia nella foresta a sud-ovest e scaccia i Windshaper che trovi lì.", nil, "A volte faccio fatica a distinguere tra il fanatismo cieco del culto degli Al'Aketh e l'ostinato rifiuto dei Windshaper di cambiare.\n\nSe credessero davvero che i venti ci guideranno, dovrebbero percepire la direzione in cui soffiano e seguirne il flusso, invece di andare loro contro.", 0x28568d0e, 0x3affac9b, 0x4e24f697, nil, 0x545f7f62, "...m." },
  [94414] = { "Le ancore di Zephras", "Parla con Halaan Hawk-Eye e fatti prestare il suo dono per osservare il pilone d'ancoraggio in lontananza.", "Salute, giovane {name}. Vengo spesso qui a contemplare l'antico pilone d'ancoraggio. Doni degli spiriti dei venti, i piloni legano e sostengono la nostra isola. Di recente, però, la loro magia è diventata instabile e incostante.\n\nNon vedo alcun segno di sofferenza. Il loro splendore non è cambiato.\n\nSe vuoi, posso prestarti il mio dono perché tu possa osservarli con i tuoi occhi.", "Il mio dono è semplice, e ordinario. Non posso scrutare tra i mondi come chi possiede la vista del cielo, né posso attingere alla magia delle linee di energia sotto Zephras come fanno altri. Ma resta pur sempre un dono, e sono grato di averlo.\n\nApprezzare ciò che si ha è la chiave della felicità. Desiderare ciò che si potrebbe avere, o ciò che si è perduto, porta solo alla disperazione.", "Grazie per aver dedicato un momento a condividere questo con me. Continuerò a vegliare sul boschetto e a meditare sulle condizioni della nostra patria.", 0x238731a9, 0x1acadf70, 0x825195ca, 0x87436f19, 0x8e28660b, "....." },
  [94427] = { "Una lezione di divinità", "Parla con Tanis Alderwood a ⟦Undercity=Sepulcra⟧.", "Un principio fondamentale dell'essere paladini è la ricerca della divinità. Non si tratta di aspirare a diventare dei, ma semplicemente di perseguire il bene in sé, per amore del bene. Siamo tutti giunti qui a causa di una tragedia, in una forma o nell'altra, e sarebbe facile perdere quella grazia che in vita ci definiva come paladini.\n\nVa' a ⟦Undercity=Sepulcra⟧ e cerca Tanis Alderwood nel ⟦Trade Quarter=Quartiere del Commercio⟧. Ha bisogno di aiuto, e un po' di grazia potrebbe fargli molto bene.", nil, "Tu... tu sei <un/una> {class}? Ti prego, non farmi del male. L-lo so che non dovrei mendicare. Non ho niente contro di te o il tuo ordine. Lasciami in pace, ti supplico!", 0x58def706, 0xf413a91f, 0x7c21c569, nil, 0xf3a1f005, "...m." },
  [94434] = { "Una lezione di divinità", "Porta 10 ⟦Linen Cloth=Tessuto di Lino⟧ a Tanis Alderwood a ⟦Undercity=Sepulcra⟧.", "Aspetta, vuoi... aiutarmi? Perché mai un paladino dovrebbe voler aiutare un mendicante come me?\n\nBe', suppongo che potresti rendermi un servizio.\n\nVedi, si tratta di mia moglie. Lei, ecco... sta cadendo a pezzi. E lo dico in senso letterale. Gli speziali potrebbero ricucirla e rimetterla in sesto in un attimo, ma sono occupati con gli affari della Dama Oscura e nessuno è libero di aiutarci. Se potessi portarmi un po' di stoffa nuova, potrei almeno farle una fasciatura per tenerla insieme mentre aspettiamo gli speziali.", "Spero di non esserti di troppo disturbo, nobile {class}.", "È molto gentile da parte tua, {class}. Davvero molto gentile.", 0x58def706, 0xde430c6a, 0x44288d78, 0x802e37b7, 0x14051e15, "....." },
  [94435] = { "Una lezione di divinità", "Torna da Danitha Morr a Bandarion Keep.", "Non so perché tu abbia fatto di tutto per aiutarmi, ma te ne sono grato. Se qualcuno ti ha mandato da me, di' anche a quella persona che le sono grato. In Tanis Alderwood avrai sempre un amico, {class}.", nil, "Hai fatto bene, {name}. Era una piccola cosa, ma anche piccoli gesti di servizio come questo possono aiutare a rafforzare il nostro legame con la Luce.\n\nLa Dama Oscura e molti al suo servizio diffidano di noi. Alcuni tramano persino contro di noi, ma risponderemo al loro scetticismo e alla loro paura con coraggio e rettitudine. Mostreremo loro che siamo membri dei Reietti e che siamo pronti a fare la nostra parte, grande o piccola che sia, per aiutare il nostro popolo a prosperare di nuovo.\n\nPrendi questo simbolo: ti servirà per ciò che verrà dopo.", 0x58def706, 0x4528f784, 0xb51d252f, nil, 0x44a723ff, "...m." },
  [94436] = { "Una lezione di divinità", "Parla con la Guardia della Morte Billmuth a Bandarion Keep.\n\nSe perdi il tuo ⟦Symbol of Life=Simbolo della Vita⟧, torna da Danitha Morr per averne un altro.", "È tempo di dimostrare la tua capacità di incanalare uno dei più grandi doni della Luce.\n\nL'oggetto che ti ho appena dato si chiama ⟦Symbol of Life=Simbolo della Vita⟧. Fa' attenzione: maneggiare un talismano della Luce come questo potrebbe causarti un certo disagio. La Luce sarà pure un anatema per la forza che ci ha creati, ma resta la nostra guida e alleata. Il dolore ce lo ricorda.\n\nVa' dalla Guardia della Morte Billmuth, al piano di sotto. È appena arrivato e ci ha chiesto aiuto. Mostra a lui e ai Reietti che cosa sa fare un vero paladino.", nil, "Allora mi aiuterai? Bene, bene. Ammetto che non vado fiero di essermi ridotto a... be', a chiedere aiuto ai paladini. I sacerdoti mi hanno mandato via, e tu potresti essere l'unica speranza del mio amico.\n\nTi prego, aiutami.", 0x58def706, 0x5c7b44af, 0xb27ae887, nil, 0x717a9a7b, "...m." },
  [94438] = { "Una lezione di divinità", "Prendi il ⟦Symbol of Life=Simbolo della Vita⟧ e usalo per resuscitare la Guardia della Morte Falgan nella ⟦Venomweb Vale=Valle Tela Venefica⟧.\n\nSe perdi il tuo ⟦Symbol of Life=Simbolo della Vita⟧, torna da Danitha Morr per averne un altro.", "Falgan e io siamo stati mandati in missione a perlustrare le attività degli scarlatti nella ⟦Venomweb Vale=Valle Tela Venefica⟧. Siamo riusciti ad avvicinarci abbastanza a uno dei loro accampamenti da sentir parlare di nuovi ordini che riguardano un attacco a Brill. Prima che potessimo decidere il da farsi, ho pestato un ramoscello e il rumore li ha messi in allarme.\n\nFalgan mi ha urlato di scappare, e io sono scappato. Quando mi sono accorto che non era con me, ero già a metà strada da Brill. Quell'idiota coraggioso sarà rimasto indietro per trattenerli e coprirmi la fuga.\n\nTi prego, trova il mio amico e aiutalo, se puoi.", nil, "Sono... tornato? E salvato da <un/una> {class}, per giunta? Vedo che porti un ⟦Symbol of Life=Simbolo della Vita⟧. Non ne vedevo uno da... be', da prima della guerra, quando Lordaeron era un luogo molto diverso. Posso solo supporre che tu sia qui per aiutare. Billmuth e io siamo stati mandati qui a perlustrare le attività degli scarlatti, e abbiamo scoperto che stanno preparando una specie di attacco.\n\nSe vuoi aiutare ancora, forse c'è altro che puoi fare per i Reietti.", 0x58def706, 0xc86dfaf3, 0x7442e1a0, nil, 0x4251ced7, "...m." },
  [94440] = { "Una lezione di divinità", "Recupera gli Scarlet Crusade Attack Plans dagli Scarlet Crusader nella ⟦Venomweb Vale=Valle Tela Venefica⟧ e torna dalla Guardia della Morte Billmuth a Bandarion Keep.", "I soldati della Crociata Scarlatta portano spesso con sé delle bisacce con i loro ordini di schieramento. Sappiamo che un attacco è imminente, ma se riusciamo a recuperare i loro ordini, possiamo avvertire il resto della Guardia della Morte e preparare un'imboscata.\n\nSi vede che sei <un/una> paladin<o/a> straordinari<o/a>. Uccidi queste bestie scarlatte, recupera una copia dei loro ordini e portala alla Guardia della Morte Billmuth. Penserà lui al resto.", "Che notizie porti della Guardia della Morte Falgan?", "Grazie per aver salvato il mio amico, {name}. Porterò questi piani al mio comandante e daremo a quei crociati un benvenuto che non dimenticheranno.\n\nSo che molti tra la nostra gente diffidano di voi paladini, ma per me è chiaro che appartieni ai Reietti fino al midollo. Non lo dimenticherò, e farò in modo che anche gli altri sappiano cosa hai fatto qui oggi.", 0x58def706, 0xa1d6b54d, 0x03204cbb, 0x310d83d6, 0xf2ce722f, "....." },
  [94441] = { "Una lezione di divinità", "Parla con Danitha Morr nella fortezza di Bandarion Keep.", "Ti prego, porta i miei ringraziamenti a Danitha Morr e dille che il resto della Guardia della Morte saprà del servizio che i paladini di Bandarion Keep ci hanno reso.\n\nHai grandi doti da paladino, e sono fiero di avere quelli come te tra le file dei Reietti. Che la Dama Oscura vegli su di te, {name}.", nil, "Il ⟦Symbol of Life=Simbolo della Vita⟧ può essere usato solo da <un/una> {class} che sia pront<o/a> a servirsi di una delle più grandi benedizioni della Luce. Sono fiera di contarti tra noi, e ora ti concedo il dono della redenzione. Con esso potrai resuscitare i tuoi compagni caduti. Usa con saggezza questo nuovo dono.\n\nHai servito bene sia i Reietti sia i paladini di Tyr's Watch. Ogni passo che possiamo compiere per conquistare i cuori e le menti dei nostri fratelli Reietti vale ampiamente lo sforzo. Va' con la Luce, {name}.", 0x58def706, 0x5ae2079a, 0xbb76e47b, nil, 0x9201f4b7, "...m." },
  [94449] = { "Il richiamo del fuoco", "Trova Bruegs Kindleborn a Dun Morogh.", "È passato molto dall'ultima volta che sei stat<o/a> mess<o/a> alla prova, {name}. Hai dimostrato pazienza, sì, ma ora è tempo che tu impari il caos... la distruzione. Il richiamo del fuoco è forte, e se sei <pronto/pronta> a pagarne il prezzo, ti parlerà.\n\nCerca Bruegs Kindleborn, lontano a est tra le montagne. Vive in una grotta sopra l'⟦South Gate Outpost=Avamposto Meridionale⟧. Lui saprà se sei davvero <pronto/pronta>.", nil, nil, 0x53f3b76b, 0x15200cd4, 0xf3c2198f, nil, nil, "...mm" },
  [94465] = { "Il richiamo del fuoco", "Porta la ⟦Torch of the Dormant Flame=Torcia della Fiamma Sopita⟧ a Braldir Ashmantle a Loch Modan.", "Sì, hai la forza per portare il totem del fuoco, <ragazzo/ragazza>, ma la forza da sola non basta a renderti <pronto/pronta>.\n\nOltre la Valley of Kings, tra le rupi di Loch Modan, c'è un sentiero nascosto che porta a una delle nostre vette sacre. Lì Braldir Ashmantle custodisce lo Shrine of the Dormant Flame.\n\nPortagli questa torcia: dimostra le tue intenzioni. Riportala accesa dal braciere del santuario e farò in modo che tu ti guadagni il totem come si deve.", nil, nil, 0x53f3b76b, 0xef8da8e8, 0x415200cc, nil, nil, "...mm" },
  [94466] = { "Il richiamo del fuoco", "Porta 1 ⟦Fire Tar=Catrame di Fuoco⟧ e 1 ⟦Reagent Pouch=Borsa dei Reagenti⟧ a Braldir Ashmantle a Loch Modan.", "Bah, non avrai fatto tutta questa strada per sentire storie, eh, {name}? Cerchi la Fiamma Eterna e il totem del fuoco.\n\nPrima di tutto, ti servirà un sapta per legare il tuo spirito alla fiamma.\n\nTe lo preparerò io, ma mi servono due cose: catrame di fuoco dai Tunnel Rat Geomancer nelle grotte dei kobold a nord, e una borsa dei reagenti da uno Stonesplinter Seer che si aggira sulle colline a sud. Un lavoro pericoloso, ma degno della fiamma.", nil, nil, 0x53f3b76b, 0x1ec23f46, 0x08842bb0, nil, nil, "...mm" },
  [94467] = { "Il richiamo del fuoco", "Sconfiggi la Minor Manifestation of Fire e metti la ⟦Glowing Ember=Brace Luminosa⟧ nel braciere in cima allo Shrine of Eternal Flame.", "Il sapta di fuoco è pronto, {name}. Ora affronterai la fiamma. Usalo al santuario, poi sali sulla vetta. Lì vedrai lo spirito: non attaccherà finché non lo farai tu, ma saprà che lo vedi.\n\nColpisci in fretta, <ragazzo/ragazza>. Più aspetti, più arde forte. Quando cade, prendi le sue braci luminose e mettile nel braciere. Accendi la torcia e guadagnati il favore del fuoco.", nil, nil, 0x53f3b76b, 0x7d09c623, 0xbfb4503b, nil, nil, "...mm" },
  [94468] = { "Il richiamo del fuoco", "Porta la Torch of Eternal Flame a Bruegs Kindleborn a Dun Morogh.", "Con la torcia ben stretta in mano, ti allontani dal braciere e guardi Loch Modan dall'alto. Senti un'eccitazione che ti scuote lo spirito mentre il vento si alza e costringe la fiamma a danzare violentemente.\n\nTi incammini lungo il sentiero che riporta a Dun Morogh, in cerca di Bruegs Kindleborn.", nil, nil, 0x53f3b76b, 0x8fb8c297, 0x74b18970, nil, nil, "...mm" },
  [94472] = { "⟦Earth Sapta=Sapta di Terra⟧", "Parla con Teo Hammerstorm per avere un altro ⟦Earth Sapta=Sapta di Terra⟧.", nil, nil, "Prendi questa e ricorda: è sacra.", 0x9c7e1740, 0x0b15db68, nil, nil, 0x794bb81e, "..mm." },
  [94473] = { "⟦Fire Sapta=Sapta di Fuoco⟧", "Parla con Braldir Ashmantle per avere un altro ⟦Fire Sapta=Sapta di Fuoco⟧.", nil, nil, nil, 0xe8738c8b, 0x60e76b9e, nil, nil, nil, "..mmm" },
  [94484] = { "Un silenzio inquietante", "Trova Elegael Thornpaw nella parte nord-orientale della Shadowgale Forest e parla con lei.", "Un momento, se permetti, {name}. Sei dirett<o/a> verso la Shadowgale Forest? Lì c'è un conclave di druidi, in una grotta a nord-est. Aspetto loro notizie, ma la loro corrispondenza è in ritardo da tempo.\n\nCon Ban'aethall in rovina e tutti i disordini di questo periodo, temo che sia successo qualcosa di terribile. Ti prego, se puoi, va' a cercare Elegael Thornpaw e metti il mio animo in pace.", nil, "Grazie al cielo il nostro messaggio è arrivato a Lotheluum. Aspetta, dove sono gli altri rinforzi? Non avranno mandato soltanto te?\n\n<Elegael impallidisce mentre le riferisci la tua conversazione con Lotheluum.>\n\nQuindi il messaggio non è arrivato. Allora siamo davvero in guai seri.\n\nA quanto pare dobbiamo cavarcela da soli. Il tempo stringe.", 0xa432cf89, 0xabfdd6fd, 0x39195fc1, nil, 0xe259eba5, "...m." },
  [94485] = { "Le lacrime della Dama", "Raccogli $N1 Lady's Tear Moss.", "Se vogliamo salvare i miei compagni nel Nightclaw Den, mi serviranno alcuni ingredienti per un impiastro. Il primo e più importante è un muschio filamentoso chiamato Lady's Tear. Di solito cresce alla base degli alberi qui a Shadowgale.\n\nQuesto muschio secerne una sostanza appiccicosa che fa da antisettico ed è perfetta per fasciare le ferite aperte. Ho raccolto quel poco che riesco a raggiungere, ma so che in questa foresta ce n'è dell'altro.\n\nVa' e fa' presto. Ce ne servirà parecchio, se i feriti che ho lasciato indietro sono ancora vivi.", "Hai trovato il Lady's Tear?", "<Elegael prende da te il mucchio di muschio appiccicoso con un debole sorriso.>\n\nGrazie, {name}, hai fatto un buon lavoro. È proprio ciò che ci serve.", 0x58e6b1d0, 0xfef31217, 0xb28e5c04, 0xa4512f51, 0x12fdd838, "....." },
  [94486] = { "Piume per fasciare", "Raccogli $N1 piume dagli Shadowgale Shriekling nella Shadowgale Forest.", "L'altro ingrediente che mi serve per l'impiastro sono le piume degli shriekling di Shadowgale che si aggirano in questa foresta. Da giovani, gli shriekling hanno piume isolanti, ideali da mettere sopra il muschio. Queste piume impediranno alla linfa antisettica di seccarsi e daranno almeno un po' di protezione dalle intemperie.\n\nAttent<o/a>: di solito gli shriekling sono docili, ma ultimamente sono diventati incredibilmente ostili. I loro grossi artigli possono sventrarti senza fatica, se non stai attent<o/a>.", "Mi addolora profondamente chiederti di uccidere i giovani shriekling, ma con la loro aggressività in aumento è la cosa migliore. Possiamo gestire solo un certo numero di emergenze alla volta.", "Grazie per queste. Userò ogni singola piuma, così il loro sacrificio non sarà vano.", 0x311c98a1, 0x06470144, 0xcbaac9a6, 0x385872fb, 0x9943ca25, "....." },
  [94487] = { "Indesiderati e indegni", "Raccogli $N1 Bloodied Heirloom dagli Al'Aketh Footsoldier e dagli Al'Aketh Stormchaser nella Shadowgale Forest.", "I cultisti degli Al'Aketh ci hanno teso un'imboscata senza alcun preavviso, anche se le loro ragioni restano per me un mistero. Sapevo che questi cultisti avevano la testa fra le nuvole, ma non avrei mai immaginato che avrebbero sconvolto con tanta brutalità il delicato equilibrio qui su Zephras. Va', uccidine quanti più puoi e prendi i loro cimeli di famiglia, se ne portano.\n\n<Elegael sputa.>\n\nQuesti cultisti maledetti dalle tempeste non meritano di essere chiamati shen'dorei. Che le bestie della foresta si prendano i loro corpi. Le loro ceneri non meritano i venti.", "Farò pagare al culto ogni goccia di sangue di druido che ha versato oggi.", "<Elegael guarda con angoscia i cimeli di famiglia insanguinati.>\n\nTante giovani vite, con tanto potenziale, ora perdute per sempre. Grazie per averli riportati, {class}.\n\nLi custodirò al sicuro finché non potrò portarli all'alto anziano. Lì potranno tornare nella collezione e attendere che la prossima generazione, forse più degna, raggiunga la maggiore età.", 0x77a04507, 0xec40e0a6, 0x29badda2, 0xc4497c3b, 0x61cecea0, "....." },
  [94488] = { "I legami che uniscono", "Uccidi Commander Haalien e porta la sua testa a Elegael Thornpaw nella Shadowgale Forest.", "Il motivo della presenza dei cultisti qui mi lascia ancora perplessa, ma sotto l'odore del sangue sento un odore familiare.\n\nUno dei druidi del nostro circolo, Haalien, è scomparso mesi fa. A quanto pare quel miserabile si è unito ai cultisti.\n\nMostragli cosa succede a chi versa il sangue dei suoi simili! Prendi la sua testa e riportamela.", "Le vite dei nostri fratelli valgono davvero così poco per te, Haalien?", "<Elegael fa una smorfia davanti alla testa mozzata, ma annuisce seccamente.>\n\nGrazie, {name}. Per quanta rabbia abbia dentro di me, mi sarebbe stato difficile abbattere mio cugino.\n\nNon piangerlo. La sua ignoranza e la sua malvagità hanno ucciso molti innocenti oggi.", 0x0b0f4638, 0xa82e2486, 0x0a7343f3, 0xf01d0886, 0xd288d221, "....." },
  [94489] = { "Le ferite del tradimento", "Entra nel Nightfang Den, cura $N1 druidi e trova Jorel Windsinger nella Shadowgale Forest.", "Ho finito gli impiastri. Presto, portali ai druidi nella grotta, a nord, appena oltre la radura. So che i miei fratelli sono in condizioni ben più gravi delle mie. Probabilmente sono troppo feriti per curarsi da soli. Siamo così pochi, noi druidi shen'dorei, che ogni vita è preziosa.\n\nPrima che tu vada, ho una richiesta egoista. Il mio compagno, Jorel Windsinger, era in condizioni gravissime quando sono partita. Ti prego, cura le sue ferite, se è ancora vivo.", nil, "<Il volto di Elegael impallidisce mentre le riferisci la sorte di Jorel e le condizioni degli altri druidi.>\n\nNo... no! È molto peggio di quanto avessi...\n\n<Elegael soffoca un singhiozzo e digrigna i denti, lasciandosi sfuggire un ringhio di dolore.>\n\nLa pagheranno. La pagheranno TUTTI. Chiunque si allei con gli Al'aketh sentirà la mia ira! Lo giuro.", 0xf524491f, 0x70ebec30, 0x3d5bdf31, nil, 0x6a75bca2, "...m." },
  [94490] = { nil, "Porta il Ripped Missive a Elegael Thornpaw nella Shadowgale Forest.", "<Infilato sotto uno dei bracciali di Haalien c'è un messaggio, un po' strappato e macchiato di sangue durante il combattimento. Sembra contenere informazioni utili sulle ragioni dell'attacco dei cultisti al rifugio dei druidi. A Elegael interesserebbero queste informazioni.>", nil, "Erano qui per il pilone? Ma a che scopo? Non eravamo noi il vero motivo del loro attacco?\n\n<Elegael si interrompe, tremando di rabbia mentre legge.>\n\nHanno massacrato la mia gente perché eravamo un intralcio! Farò a pezzi ogni cultista con le mie zanne! Farò in modo che nessuno lasci questo posto vivo.\n\nVa', presto! Se gli ordini venivano davvero da Valanaar, vuol dire che probabilmente lì si nasconde un traditore. Consegna il messaggio a Lotheluum a Valanaar e raccontagli cos'è successo.", 0xab8b8528, 0x38e9ba67, 0xc2dcf852, nil, 0xb05a5f41, "e..m." },
  [94491] = { "Il destino del rifugio", "Consegna il messaggio a Lotheluum a Valanaar e raccontagli cos'è successo.", "A quanto pare c'è un informatore nascosto da qualche parte a Valanaar che passa notizie al culto. Io non sono certo in condizione di affrontare il viaggio, ma Lotheluum deve sapere cos'è successo qui.\n\nDeve anche conoscere la sorte di chi non è più con noi. Grazie al tuo aiuto credo che da qui in poi potremo occuparci noi del resto, anche se il danno ormai è fatto.\n\nTi prego, va' in fretta, {name}. Spero che un giorno le nostre strade si incrocino di nuovo. Fino ad allora, ho dei cultisti da uccidere.", nil, "<Lotheluum ha un'espressione di autentico terrore mentre racconti gli eventi del rifugio dei druidi.>\n\nIo... mi dispiace, {name}. Mi serve solo un momento. Non ho parole per descrivere questa perdita.\n\nÈ davvero una notizia grave. Se questo messaggio non è falso, allora qui a Valanaar abbiamo, nel migliore dei casi, un complice e, nel peggiore, un traditore. Lo porterò subito all'alto anziano! Non lascerò che il sacrificio dei miei compagni sia vano.", 0xef28fcc3, 0xbbf76165, 0x96f26dcc, nil, 0x880d65a8, "...m." },
  [94493] = { "Un sacrificio vano", "Parla con Elegael Thornpaw nella parte nord-orientale della Shadowgale Forest.", "Grazie al cielo il nostro messaggio è arrivato a Lotheluum. Aspetta, dove sono gli altri rinforzi? Non avranno mandato soltanto te?\n\n<Elegael impallidisce mentre ti spieghi.>\n\nQuindi il messaggio non è arrivato a Valanaar. Allora siamo davvero in guai seri.\n\n<Elegael sospira profondamente, poi assume un'aria risoluta.>\n\nAllora dobbiamo cavarcela da soli. Il tempo stringe.", nil, nil, 0xaf28bd4e, 0xfc76d336, 0x11488683, nil, nil, "...mm" },
  [94494] = { "Il richiamo dell'acqua", "Trova Norric Lochthane a Loch Modan.", "È passato molto tempo dall'ultima volta che sei stat<o/a> mess<o/a> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento che tu impari la purezza dell'acqua.\n\nCerca Norric Lochthane a Loch Modan. Si trova lungo la sponda nord-occidentale del lago, a sud della ⟦Stonewrought Dam=Diga di Pietrasalda⟧. Lo troverai lì, nella sua casupola. Buona fortuna, {name}.", nil, nil, 0x1f0e11aa, 0xa614e79c, 0xf11bb23d, nil, nil, "...mm" },
  [94495] = { "Il richiamo dell'acqua", "Trova Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Se c'è una verità che devi imparare sull'acqua, è questa: l'acqua significa rinascita. Scava la pietra, lava la sporcizia e guarisce gli stanchi, ma solo quando è pura. Contaminala e rovinerà tutto ciò che tocca.\n\nSe cerchi il sapta d'acqua, trova Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧. La sua famiglia vive in una grotta sotto le cascate meridionali.\n\nSu, vai, non lasciare che il fiume corra più veloce di te.", nil, nil, 0x1f0e11aa, 0xadc7f213, 0xadd95e2e, nil, nil, "...mm" },
  [94497] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Brown Waterskin=Borraccia Marrone Vuota⟧ ai piedi delle cascate sotto la grotta di Hervdana e riportagliela nelle ⟦Wetlands=Paludi Grigie⟧.", "Ah, quindi sei venut<o/a> a cercare il sapta, eh? Be', allora ascolta bene, <caro/cara>. Per trovare la comprensione e guadagnarti il sapta, devi cercare l'acqua nelle sue varie forme. Mentre raccogli i campioni, tieni gli occhi aperti. Osserva le bestie che la custodiscono, la terra che nutre e come cambia le vite.\n\nCominciamo con qualcosa di semplice: riempi questa borraccia ai piedi delle cascate, dove l'acqua dolce incontra quella salmastra. Su, vai, e attent<o/a> alla palude.", nil, nil, 0x1f0e11aa, 0xa3d8f378, 0x4ed51e9b, nil, nil, "...mm" },
  [94499] = { "Il richiamo dell'acqua", "Riempi la ⟦Empty Red Waterskin=Borraccia Rossa Vuota⟧ alle ⟦Stonewatch Falls=Cascate di Guardamasso⟧, vicino ai Nightcrawler Murloc, e torna da Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Sì, ⟦Redridge=Crestarossa⟧ beve a piene mani dal ⟦Lake Everstill=Lago Placido⟧, ma quando le acque precipitano giù per le ⟦Stonewatch Falls=Cascate di Guardamasso⟧, qualcosa ci si è infiltrato. I murloc laggiù sono bestioni grossi e deformi. Non come quelli che trovi qui o al Loch. Per fortuna dei paesani, restano ai piedi delle cascate.\n\nPortami un campione. Ho intenzione di scoprire se è magia, veleno o qualcosa di peggio a contaminare le acque vicino a quel vecchio forte.", nil, nil, 0x1f0e11aa, 0x6ccca7b4, 0xa2cb5a4a, nil, nil, "...mm" },
  [94500] = { "Il richiamo dell'acqua", "Riempi la Unfilled Blue Waterskin alle acque di Astranaar, a ⟦Ashenvale=Valtetra⟧, e torna da Hervdana Saegrund nelle ⟦Wetlands=Paludi Grigie⟧.", "Prendi questa borraccia e addentrati nell'ombra smeraldina di ⟦Ashenvale=Valtetra⟧. Astranaar riposa cullata da acque non toccate dalla corruzione. Il fondo del lago è disseminato di rovine, tracce di un'epoca passata. Riportami un campione dal lago. Acqua pura, antica e forse incantata.\n\nÈ l'ultimo liquido che mi serve prima di rimandarti da Norric.\n\nPrendi la nave da Menethil per Auberdine. Lungo il tragitto fa scalo a ⟦Southshore=Riva del Sud⟧.\n\nE sta' attent<o/a>... la foresta ha occhi, e non battono ciglio.", nil, nil, 0x1f0e11aa, 0x76aef756, 0xc7e05766, nil, nil, "...mm" },
  [94501] = { "Il richiamo dell'acqua", "Porta la ⟦Vial of Purest Water=Fiala d'Acqua Purissima⟧ a Norric Lochthane a Loch Modan.", "Norric avrà un ultimo compito per te prima di ricompensarti con i riti del totem dell'acqua. La fiala d'acqua che ti ho dato è necessaria per quel compito, qualunque esso sia. Ora va' a cercarlo. Un giorno ci rivedremo.", nil, nil, 0x1f0e11aa, 0x0d508544, 0x58506c33, nil, nil, "...mm" },
  [94502] = { "Il richiamo dell'acqua", "Bevi il ⟦Water Sapta=Sapta d'Acqua⟧ e purifica la corruzione allo ⟦Stendel's Pond=Stagno di Stendel⟧, nelle ⟦Westfall=Marche Occidentali⟧.\nQuando hai finito, torna da Norric a Loch Modan.", "Nelle ⟦Westfall=Marche Occidentali⟧, fuori da ⟦Moonbrook=Rivoluna⟧, si trova lo ⟦Stendel's Pond=Stagno di Stendel⟧. Un tempo era una sorgente pura, ora è stata toccata da forze oscure. Gli spiriti di quel luogo sono ammutoliti.\n\nDevi bere il sapta d'acqua, poi affrontare la corruzione che insozza le acque. Prendi i suoi bracciali e le ultime gocce della pozione di Hervdana, poi mettili sul santuario. Questo richiamerà uno spirito, purificato e sincero. Parlagli, impara ciò che puoi.\n\nPortami la prova che il compito è svolto e ti concederò il totem.", nil, nil, 0x1f0e11aa, 0x3dec7b07, 0x1215dd1a, nil, nil, "...mm" },
  [94503] = { "Il richiamo dell'acqua", "Parla con la Minor Manifestation of Water nelle ⟦Westfall=Marche Occidentali⟧.", "Una luce erompe mentre l'ultima parola ti lascia le labbra. Il sibilo dell'acqua che si fa vapore svanisce nel silenzio e i tuoi sensi vacillano mentre gli spiriti corrotti intorno a te si dissolvono, la loro essenza dispersa come cenere nel vento.", nil, nil, 0x1f0e11aa, 0x2cab5030, 0x31813519, nil, nil, "...mm" },
  [94505] = { "Il richiamo dell'acqua", "Porta la ⟦Shard of Water=Scheggia d'Acqua⟧ a Norric Lochthane a Loch Modan.", "Prendi scheggia. Prendi scheggia e dai vita.\n\nDai vita e comprendi. Comprendi che acqua è vita... corruzione ferma vita.\n\nTu proteggi e dai vita con potere dell'acqua.", nil, nil, 0x1f0e11aa, 0x038a8a5c, 0x1bc4c72c, nil, nil, "...mm" },
  [94559] = { nil, "Cerca l'Al'Aketh Turncoat negli Shen'dar Highlands.", "Tra gli Al'Aketh c'è un voltagabbana. Sostiene di conoscere le vere intenzioni del culto riguardo all'isola e vuole passare dalla nostra parte, ma lo farà solo se gli garantiamo protezione.\n\nQuesto disertore si nasconde in una casa poco a nord-ovest di Valanaar, appena dentro gli altopiani. Mi serve qualcuno che possa andarci con discrezione, trovare il traditore, scoprire cosa sa e scortarlo da noi. Potrebbe essere una trappola, ma se queste informazioni sono importanti quanto sostiene il traditore, vale la pena di correre qualche rischio.", nil, nil, 0xe7944cd2, 0x1c0f7bd4, 0x717f16b2, nil, nil, "e..mm" },
  [94568] = { "I veri piani del culto", "Parla con Talaanis Shadowsong e assisti alla conversazione.", "Il voltagabbana aveva chiaramente paura di ciò che il culto aveva in mente, tanto da disertare e cercare il nostro aiuto. È davvero un peccato che sia morto e si sia portato i suoi segreti nella tomba.\n\nDobbiamo discuterne ancora per decidere le nostre prossime mosse.", nil, "Potremmo provare a mandare i custodi della pace ad affrontare direttamente le forze del culto, ma in campo aperto non ce la caveremmo bene contro di loro.\n\nCi servirà un approccio diverso.", 0xb5a1a1cb, 0x8a14b2e2, 0x0db307b1, nil, 0xe24a2261, "...m." },
  [94616] = { "⟦Water Sapta=Sapta d'Acqua⟧", nil, nil, nil, nil, 0xcd2fb34a, nil, nil, nil, nil, ".mmmm" },
  [94638] = { "Forza e pietà", "Trova e uccidi Ur'endra negli Shen'dar Highlands.", "Sei venut<o/a> da me sperando di imparare ad assumere una forma di forza. Ho un compito per te, anche se mi pesa sul cuore.\n\nLa mia compagna, Ur'endra, si è persa nella follia e ha cominciato ad attaccare i suoi simili. Senza la magia dei venti, molte creature hanno cominciato a perdere se stesse... Ur'endra compresa. Ha la sua tana in una grotta a ovest di qui, tra le scogliere lungo il confine fra gli Shen'dar Highlands e i Gustberry Lowlands.\n\nMetti fine alle sue sofferenze e ti concederò la mia benedizione.", nil, nil, 0x063a7e36, 0xbdfde440, 0x62e9d1a9, nil, nil, "...mm" },
  [94773] = { "Grazia divina", nil, nil, nil, nil, 0x4199a5e1, nil, nil, nil, nil, ".mmmm" },
  [94774] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla ⟦Cathedral of Light=Cattedrale della Luce⟧ a ⟦Stormwind=Roccavento⟧ il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e sono pronti a proseguire il tuo addestramento. Quando arrivi, cerca la somma sacerdotessa Laurena. Saprà guidarti oltre. Buona fortuna, e che la Luce sia con te.", nil, nil, 0x4199a5e1, 0x8de762b6, 0xb0903ab5, nil, nil, "...mm" },
  [94775] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Elune ti benedica, {race}. Spero che la tua Luce ti trovi e ti protegga bene in questo giorno.\n\nUno dei vostri sacerdoti è passato di qui non molto tempo fa a cercarti. Ha detto che dovresti tornare alla ⟦Cathedral of Light=Cattedrale della Luce⟧ il prima possibile per parlare con la somma sacerdotessa Laurena. Pare che tu abbia fatto bene, per attirare tanta attenzione. Non mi tratterrei troppo qui: la tua gente ha bisogno di te.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x93d8c9e5, nil, nil, "...mm" },
  [94776] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "È ora che tu vada a ⟦Stormwind=Roccavento⟧, {name}. La somma sacerdotessa Laurena, nella ⟦Cathedral of Light=Cattedrale della Luce⟧, vuole parlarti. Dev'essere qualcosa di molto buono o di molto brutto se la somma sacerdotessa ti vuole lì di persona, ma scommetto che hai solo fatto bene e che è una buona cosa che voglia parlarti.\n\nMa non perdere troppo tempo da queste parti. Io ci andrei il prima possibile.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x0e82ce63, nil, nil, "...mm" },
  [94777] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Poco tempo fa uno dei vostri sacerdoti è passato di qui a cercarti, {race}. Ha detto che, se ti avessi vist<o/a>, avrei dovuto indirizzarti verso la ⟦Cathedral of Light=Cattedrale della Luce⟧. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto non tarderei troppo ad andarci.\n\nElune sia con te, {race}.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x1cfc2115, nil, nil, "...mm" },
  [94778] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "C'è bisogno di te a ⟦Stormwind=Roccavento⟧, {name}. La somma sacerdotessa del posto, Laurena, dice che è giunto il momento di dimostrare che sei <degno/degna> del prossimo livello del tuo addestramento. Non perdere troppo tempo per arrivarci. La troverai nella ⟦Cathedral of Light=Cattedrale della Luce⟧, al centro della città. Portale i miei saluti e dimostra quanto sei <degno/degna> di una tale vocazione. La Luce sia con te, {name}.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x8ea469d6, nil, nil, "...mm" },
  [94779] = { "Grazia divina", "Parla con la somma sacerdotessa Laurena a ⟦Stormwind=Roccavento⟧.", "Sia lodata Elune, e la tua Luce, {name}.\n\nPiù o meno in questo periodo, molti del nostro ordine apprendono abilità che riflettono la loro fede in Elune. Se non ricordo male, credo che lo stesso valga anche per il tuo ordine.\n\nQuando avrai concluso i tuoi affari a Darnassus, cercherei una delle vostre somme sacerdotesse per proseguire l'addestramento.", nil, nil, 0x4199a5e1, 0x8de762b6, 0x9d972e4f, nil, nil, "...mm" },
  [94789] = { "Il richiamo dell'aria", "Trova Veyric Thundervein negli ⟦Arathi Highlands=Altopiani d'Arathi⟧.", "I venti d'Azeroth ti salutano, e presto starai tra alcuni dei nostri più potenti fratelli. Sono fiero di vedere quanta strada hai fatto: il tuo futuro è davvero luminoso.\n\nL'elemento dell'aria è difficile da padroneggiare, ma ho fiducia che la tua abilità ti farà superare qualsiasi prova.\n\nDirigiti a nord, negli ⟦Arathi Highlands=Altopiani d'Arathi⟧. Tra le colline settentrionali troverai Veyric Thundervein. Lui t'insegnerà di più.", nil, nil, 0x8f4acf86, 0xe1756af1, 0x9b177a55, nil, nil, "...mm" },
  [94792] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per addomesticare un Rockhide Boar. Fai pratica, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Josephine Carson.", "Molti cacciatori preferiscono viaggiare con compagni animali. Con una bestia al tuo fianco, scoprirai di poter sopravvivere anche nelle circostanze più pericolose. Come si dice, tutto è più facile con un amico. Tuttavia, procurarsi un compagno animale è qualcosa che va fatto con cura. L'equilibrio della natura è delicato e va sempre rispettato.\n\nPorta con te questo ⟦Taming Rod=Bastone per Addomesticare⟧ nella foresta. Con esso potrai addomesticare un Rockhide Boar e mettere in pratica le tue capacità di cacciatore.", "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x19efabbc, 0x69a91737, 0xe5057f89, 0x7f1a8496, "....." },
  [94793] = { "Addestrare la bestia", "Parla con Isaac Chan a ⟦Goldshire=Borgodoro⟧.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le capacità per addestrarlo. Per questo non c'è nessuno migliore di Isaac Chan, un uomo dei boschi da una vita. Ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nVa' con i venti, giovane {class}.", nil, "<Un/Una> {class} alle prime armi, vedo. Sì, posso darti le capacità che ti servono per addestrare e guidare il tuo famiglio. Non solo potrai insegnare al tuo famiglio nuove abilità, ma d'ora in poi potrai anche nutrirlo e riportarlo in vita, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e vivi con riverenza verso la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0xf8c4ebf2, 0x4bc880b0, nil, 0xfbd746d0, "...m." },
  [94817] = { "Lampo disorientante", nil, nil, nil, nil, 0xd8782324, nil, nil, nil, nil, ".mmmm" },
  [94818] = { "Piano di riserva", nil, nil, nil, nil, 0x584b30b7, nil, nil, nil, nil, ".mmmm" },
  [94819] = { "Piano di riserva", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "{name}, la tua somma sacerdotessa Mims vorrebbe riceverti a ⟦Ironforge=Forgiardente⟧. Affrettati, mi<o/a> abile amic<o/a>: la tua prossima prova si avvicina in fretta. Anche se vorrei poter assistere ai riti speciali della tua razza, il mio posto è qui. Ma che la Luce ti accompagni nei tuoi viaggi. Quando arriverai in città, Mims dovrebbe essere ancora nel Mystic Ward. Ti aspetterà.", nil, nil, 0x584b30b7, 0x656c5f67, 0xf8b55805, nil, nil, "...mm" },
  [94820] = { "Piano di riserva", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "La tua razza è davvero ingegnosa, {name}. Siamo fieri di chiamarvi alleati. E a ogni tramonto tu e i tuoi vi avvicinate alla riconquista della vostra città, ma con il peso di tenere al sicuro le vostre famiglie in esilio. Quella nostalgia di casa deve pesarti molto.\n\nPoco fa è giunta notizia da ⟦Ironforge=Forgiardente⟧. Chiede che tu torni là e parli con la somma sacerdotessa Mims nel Mystic Ward. Io non la farei aspettare. Che Elune guidi i tuoi viaggi.", nil, nil, 0x584b30b7, 0x656c5f67, 0xfc0c8df4, nil, nil, "...mm" },
  [94821] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Di recente un sacerdote è venuto nelle nostre sale a cercarti, giovane {race}. Ha detto di essere in missione per trovarti e che dovresti tornare alla Hall of Mysteries di ⟦Ironforge=Forgiardente⟧ il prima possibile. Quando arrivi, cerca la somma sacerdotessa Mims: ti dirà di più.\n\nChe la Luce sia con te, {name}.", nil, nil, 0xd8782324, 0x656c5f67, 0xb61e2669, nil, nil, "...mm" },
  [94822] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Hai attirato l'attenzione dei nostri superiori, {name}. Ti chiedono di recarti alla Hall of Mysteries di ⟦Ironforge=Forgiardente⟧ il prima possibile. A quanto pare ritengono che tu abbia già dato prova di te e sono pronti a portare avanti il tuo addestramento. Quando arrivi, trova la somma sacerdotessa Mims. Saprà guidarti. Buona fortuna, e che la Luce sia con te.", nil, nil, 0xd8782324, 0x656c5f67, 0xf8811e2d, nil, nil, "...mm" },
  [94823] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Elune ti benedica, buon {race}. Spero che la tua Luce ti trovi e ti protegga bene in questo giorno.\n\nUno dei tuoi sacerdoti è passato di qui non molto tempo fa a cercarti. Ha accennato al fatto che dovresti tornare il prima possibile alla Hall of Mysteries per parlare con la somma sacerdotessa Mims. Sembra che tu abbia fatto bene, per attirare tanta attenzione. Non mi tratterrei troppo qui: la tua gente ha bisogno di te.", nil, nil, 0xd8782324, 0x656c5f67, 0xf4f34293, nil, nil, "...mm" },
  [94824] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94825] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", "Poco fa uno dei vostri sacerdoti è venuto a cercarti, {race}. Ha detto che, se ti avessi visto, avrei dovuto indirizzarti verso la Hall of Mysteries. Ha detto che era molto importante, ma al tuo posto non mi preoccuperei troppo. Sembrava di buon umore... come se si trattasse di buone notizie. Al tuo posto, però, non tarderei ad andarci.\n\nChe Elune sia con te, nobile {race}.", nil, nil, 0xd8782324, 0x656c5f67, 0xa819c88b, nil, nil, "...mm" },
  [94826] = { "Lampo disorientante", "Parla con la somma sacerdotessa Mims a ⟦Ironforge=Forgiardente⟧.", nil, nil, nil, 0xd8782324, 0x656c5f67, nil, nil, nil, "..mmm" },
  [94863] = { "Addomesticare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [94864] = { "Addomesticare la bestia", nil, nil, nil, nil, 0xecd97a9a, nil, nil, nil, nil, ".mmmm" },
  [94872] = { "Comprare l'amicizia: Magram", "Porta il Totem Tote al quartiermastro dei Magram al Magram Village, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Magram Clan Centaur=Centauri del Clan Magram⟧.", nil, nil, nil, 0xf5fd14ba, 0x66df78e4, nil, nil, nil, "..mmm" },
  [94873] = { "Comprare l'amicizia: Gelkis", "Porta il Totem Tote al quartiermastro dei Gelkis al ⟦Gelkis Village=Villaggio dei Gelkis⟧, a ⟦Desolace=Desolanda⟧, per accrescere notevolmente la tua reputazione presso quel clan. Devi essere almeno Neutrale con i ⟦Gelkis Clan Centaur=Centauri del Clan Gelkis⟧.", nil, nil, nil, 0x57c3db29, 0x68c32afb, nil, nil, nil, "..mmm" },
  [94913] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, "Ah, vedo che hai già padroneggiato la forma d'orso. Bene, bene. Sei sulla buona strada, giovane {class}.", 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, 0x0e12a96b, "...m." },
  [94914] = { "⟦Moonglade=Radaluna⟧", "Usa l'incantesimo \"⟦Teleport: Moonglade=Teletrasporto: Radaluna⟧\" per raggiungere ⟦Moonglade=Radaluna⟧. Al tuo arrivo, parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Tutti i druidi sono i benvenuti nelle terre sacre di ⟦Moonglade=Radaluna⟧. Il custode Remulos, guardiano di ⟦Moonglade=Radaluna⟧, veglia su tutti i druidi che vi riposano. Ti insegnerò l'incantesimo che ti permette di trasportarti lì. Lancialo ogni volta che cerchi la conoscenza o il conforto di ⟦Moonglade=Radaluna⟧.\n\nQuanto alla tua prima lezione qui su Azeroth, recati a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze a ⟦Nighthaven=Nottequieta⟧ del sentiero che ora percorri. Buona fortuna, giovane druido.", nil, nil, 0xaeb97c8b, 0xf8085429, 0x89074bce, nil, nil, "...mm" },
  [94978] = { "Addomesticare la bestia", nil, nil, "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", nil, 0xecd97a9a, nil, nil, 0xe5057f89, nil, ".mm.m" },
  [94979] = { "Addomesticare la bestia", nil, nil, "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", nil, 0xecd97a9a, nil, nil, 0xe5057f89, nil, ".mm.m" },
